class VidaRuntimeBoundary extends React.Component {
  constructor(props){
    super(props);
    this.state={error:null,info:null};
  }
  static getDerivedStateFromError(error){ return {error}; }
  componentDidCatch(error,info){
    console.error("[VIDA runtime]",error,info);
    this.setState({info});
  }
  render(){
    if(this.state.error){
      const err=this.state.error;
      return <div style={{minHeight:"100vh",background:"#EEF3F7",padding:20,fontFamily:"system-ui",color:"#17324A"}}>
        <div style={{maxWidth:680,margin:"40px auto",background:"#fff",borderRadius:18,padding:20,boxShadow:"0 12px 34px #17324A22"}}>
          <div style={{fontSize:18,fontWeight:900,marginBottom:8}}>VIDA encontró un error de ejecución</div>
          <div style={{fontSize:12,color:"#587087",marginBottom:14}}>Copiá este bloque y mandáselo a ChatGPT/Claude. No hace falta adivinar qué pasó.</div>
          <pre style={{whiteSpace:"pre-wrap",wordBreak:"break-word",fontSize:11,background:"#F4F7FA",padding:12,borderRadius:12,overflow:"auto"}}>{String(err?.stack||err?.message||err)}</pre>
          <button onClick={()=>location.reload()} style={{marginTop:14,border:0,borderRadius:12,padding:"10px 14px",fontWeight:800,background:"#0B73B9",color:"#fff"}}>Recargar</button>
        </div>
      </div>;
    }
    return this.props.children;
  }
}

