function geneColorHex(gene,catalog,fallback){return (catalog.find(x=>x.id===gene)?.hex)||fallback;}
function appearanceFromVisualDNA(dna,style={}){
  const faceEntries=Object.entries(FACE_DNA_PRESETS);const scoreFace=([,p])=>Math.abs(p.faceWidth-dna.face.faceWidth)+Math.abs(p.faceLength-dna.face.faceLength)+Math.abs(p.jawWidth-dna.face.jawWidth);const faceShapeId=faceEntries.sort((a,b)=>scoreFace(a)-scoreFace(b))[0][0];
  const eyeEntries=Object.entries(EYE_DNA_PRESETS);const scoreEye=([,p])=>Math.abs(p.size-dna.eyes.size)+Math.abs(p.roundness-dna.eyes.roundness)+Math.abs(p.tilt-dna.eyes.tilt)+Math.abs(p.spacing-dna.eyes.spacing);const eyeShapeId=eyeEntries.sort((a,b)=>scoreEye(a)-scoreEye(b))[0][0];
  const noseEntries=Object.entries(NOSE_DNA_PRESETS);const scoreN=([,p])=>Math.abs(p.length-dna.nose.length)+Math.abs(p.bridgeWidth-dna.nose.bridgeWidth)+Math.abs(p.projection-dna.nose.projection)+Math.abs(p.tipWidth-dna.nose.tipWidth);const noseShapeId=noseEntries.sort((a,b)=>scoreN(a)-scoreN(b))[0][0];
  return normalizeAppearanceSafe({faceShapeId,skinTone:nearestSkinTone(dna.skin.melanin),hairTextureId:nearestTexture(dna.hair.texture),hairStyleId:style.hairStyleId||RandomSystem.pick(HAIR_STYLES).id,hairColor:geneColorHex(dna.hair.naturalColorGenes?.[0],HAIR_COLORS,"#4F3020"),eyeShapeId,eyeColor:geneColorHex(dna.eyes.irisGenes?.[0],EYE_COLORS,"#52351F"),eyebrowShapeId:style.eyebrowShapeId||"rectas",noseShapeId,mouthShapeId:style.mouthShapeId||"labios_medios",freckles:dna.skin.freckling>.48,moles:RandomSystem.bool(.15),outfitColor:RandomSystem.pick(OUTFIT_COLORS),visualAssets:emptyVisualAssets()});
}
function bodyFromVisualDNA(dna,gender,age=0,attractiveness=55,fitness=50){const frame=dna.body.frameSize<.4?"slim":dna.body.hipWidth>.65?"curvy":dna.body.frameSize>.65?"broad":"average";return createBodyProfile({gender,age,targetHeightCm:dna.body.heightPotentialCm,frameId:frame,attractiveness,fitness});}

