const GENETIC_CONDITIONS = [
  {id:"familial_hypercholesterolemia",name:"Hipercolesterolemia familiar",mode:"dominant",base:0.003,manifestAge:[8,35]},
  {id:"hemochromatosis",name:"Hemocromatosis hereditaria",mode:"recessive",base:0.006,manifestAge:[20,55]},
  {id:"cystic_fibrosis",name:"Fibrosis quística",mode:"recessive",base:0.0004,manifestAge:[0,4]},
  {id:"sickle_cell",name:"Enfermedad de células falciformes",mode:"recessive",base:0.001,manifestAge:[0,8]},
  {id:"marfan",name:"Síndrome de Marfan",mode:"dominant",base:0.0002,manifestAge:[5,25]},
  {id:"lynch",name:"Síndrome de Lynch",mode:"dominant",base:0.0003,manifestAge:[18,45]},
];
function randomGeneticProfile(){
  const variants={};
  GENETIC_CONDITIONS.forEach(c=>{
    const carrierChance=c.mode==="recessive"?Math.min(.12,Math.sqrt(c.base)*1.8):c.base;
    const affected=RandomSystem.bool(c.base);
    variants[c.id]=affected?"affected":(RandomSystem.bool(carrierChance)?"carrier":"clear");
  });
  return {variants,familyHistory:[]};
}
function inheritGeneticProfile(mother,father){
  const mg=mother?.genetics?.healthDNA||randomGeneticProfile();
  const fg=father?.genetics?.healthDNA||randomGeneticProfile();
  const variants={}; const familyHistory=[];
  GENETIC_CONDITIONS.forEach(c=>{
    const m=mg.variants?.[c.id]||"clear", f=fg.variants?.[c.id]||"clear";
    const givesVariant=(state)=>state==="affected"?true:state==="carrier"?RandomSystem.bool(.5):false;
    const mv=givesVariant(m),fv=givesVariant(f);
    if(c.mode==="recessive") variants[c.id]=mv&&fv?"affected":(mv||fv?"carrier":"clear");
    else variants[c.id]=(mv||fv)?(RandomSystem.bool(.5)?"affected":"carrier"):"clear";
    if(m!=="clear"||f!=="clear") familyHistory.push(c.id);
  });
  return {variants,familyHistory};
}
// ============================================================
// generatePerson — ÚNICO punto central de creación de personas nuevas.
// Cualquier pantalla que necesite un NPC (pareja, compañero de trabajo,
// compañero de escuela, amigo, abuelo, hijo de un NPC autónomo, etc.)
// debe pasar por acá en vez de armar el objeto a mano con randomAppearance()
// suelto — así todos reciben personId + visualDNA + ascendencia + país de
// nacimiento de forma consistente (Prioridad 1).
//
// context admite:
//   gender, age, countryId, name, surname, usedNames (evita nombres
//   repetidos en la misma familia), relation/role (string informativo),
//   motherDNA/fatherDNA (visualDNA de los padres: si están, hereda en vez
//   de generar de cero), motherPersonForHealth/fatherPersonForHealth
//   (personas completas, para heredar healthDNA con inheritGeneticProfile),
//   adultHeightCm, bodyFrameId, attractiveness, fitness.
// ============================================================
function generatePerson(seed, context={}){
  const id=seed||RandomSystem.id();
  const gender=context.gender||(RandomSystem.bool()?"M":"F");
  const age=context.age??RandomSystem.int(20,60);
  const countryId=context.countryId||"ar";
  const visualDNA=(context.motherDNA&&context.fatherDNA)
    ? inheritVisualDNA(context.motherDNA,context.fatherDNA,id)
    : buildVisualDNAFromSelection({appearance:randomAppearance(),countryId,gender,adultHeightCm:context.adultHeightCm,bodyFrameId:context.bodyFrameId,seed:id});
  const appearance={...appearanceFromVisualDNA(visualDNA),gender};
  const body=bodyFromVisualDNA(visualDNA,gender,age,context.attractiveness??RandomSystem.int(40,70),context.fitness??RandomSystem.int(35,70));
  const name=context.name||localizedFullName(gender,{location:{countryId}},context.usedNames||[]);
  const healthDNA=(context.motherPersonForHealth&&context.fatherPersonForHealth)
    ? inheritGeneticProfile(context.motherPersonForHealth,context.fatherPersonForHealth)
    : randomGeneticProfile();
  return {
    id, name, gender, age, alive:true, appearance, body,
    location:{countryId},
    relation:context.relation||context.role||null,
    genetics:{visualDNA,healthDNA,motherId:context.motherId||null,fatherId:context.fatherId||null},
    medical:{vision:"normal",conditions:[]},
    relationship:context.relationship??RandomSystem.int(45,75),
    ...baseNpcTraits(),
  };
}

function manifestGeneticConditions(person,pushAuto){
  const p=person; const dna=p.genetics?.healthDNA; if(!dna)return p;
  p.medical={...(p.medical||{}),conditions:[...(p.medical?.conditions||[])]};
  GENETIC_CONDITIONS.forEach(c=>{
    if(dna.variants?.[c.id]!=="affected")return;
    if(p.medical.conditions.some(x=>(x.id||x.name)===c.id||x.name===c.name))return;
    const [min,max]=c.manifestAge; if(p.age<min||p.age>max)return;
    const yearlyChance=Math.min(.65,.12+((p.age-min)/Math.max(1,max-min))*.35);
    if(RandomSystem.bool(yearlyChance)){
      p.medical.conditions.push({id:c.id,name:c.name,genetic:true,diagnosedAge:p.age,status:"active"});
      p.stats={...p.stats,health:clampStat((p.stats?.health||70)-RandomSystem.int(3,9))};
      pushAuto?.("salud",`Un estudio médico detectó ${c.name}. El informe indica que tiene un componente hereditario y quedó registrado en tu historia clínica.`,"milestone");
    }
  });
  return p;
}

