function hasDegree(person, degreeId){
  return person.university?.status==="graduated" && person.university?.degreeId===degreeId;
}
function jobUnlockedForPerson(person, job){
  if(person.age < job.minAge) return false;
  if(job.requiredDegree && !hasDegree(person, job.requiredDegree)) return false;
  return (person.academicPerformance||0) >= (job.minAcademic||0);
}
function allJobListingsFor(person){
  return [...JOB_LISTINGS, ...DEGREE_JOB_LISTINGS].filter(j=>person.age>=j.minAge);
}

function makeUniversityNpc(role, relation, age, subject=null){
  const n=makeSchoolNpc({role,relation,age});
  return {...n,subject};
}
function makeUniversityCohort(person, degree){
  const professors=degree.subjects.slice(0,Math.min(6,degree.subjects.length)).map(s=>makeUniversityNpc(`Profesor/a de ${s}`,"Profesor/a",RandomSystem.int(30,67),s));
  const classmates=Array.from({length:10},()=>makeUniversityNpc("Estudiante","Compañero/a",Math.max(18,person.age+RandomSystem.int(-2,4))));
  return {professors,classmates};
}



