function careerFallbackForSubject(subjectName){
  const s=(subjectName||"").toLowerCase();
  if(/cálculo|álgebra|física|química|termodin|material|proyecto final/.test(s))return CAREER_FALLBACK_BANKS.engineering;
  if(/derecho|contrato|procesal|constitucional|penal|laboral|administrativo|comercial/.test(s))return CAREER_FALLBACK_BANKS.law;
  if(/econom|estadística|finanzas|macroecon|microecon|política económica/.test(s))return CAREER_FALLBACK_BANKS.economics;
  if(/programación|comput|algorit|base de datos|sistemas operativos|redes|software|discreta/.test(s))return CAREER_FALLBACK_BANKS.computing;
  if(/arte|dibujo|color|composición|fotografía|estética|taller/.test(s))return CAREER_FALLBACK_BANKS.arts;
  return STUDY_QUESTION_BANK.default;
}
function studyQuestionsFor(subjectName,attempt=0){
  const bank=STUDY_QUESTION_BANK[subjectName]||careerFallbackForSubject(subjectName);
  const count=Math.min(2,bank.length);
  const start=(attempt*count)%bank.length;
  return Array.from({length:count},(_,i)=>bank[(start+i)%bank.length]);
}

