function propertyRoomList(property){
  if(property.type==="Terreno") return [{id:"land",label:"Terreno",kind:"outside"}];
  const out=[{id:"living",label:"Living",kind:"living"},{id:"kitchen",label:"Cocina",kind:"kitchen"}];
  const bedrooms=Math.max(1,Math.min(6,(property.rooms||2)-1));
  for(let i=0;i<bedrooms;i++) out.push({id:`bedroom_${i+1}`,label:`Dormitorio ${i+1}`,kind:"bedroom"});
  for(let i=0;i<(property.bathrooms||1);i++) out.push({id:`bath_${i+1}`,label:`Baño ${i+1}`,kind:"bath"});
  if(property.type==="Casa") out.push({id:"outside",label:property.style==="cottage"?"Jardín y galería":"Patio / jardín",kind:"outside"});
  return out;
}
