const LABOR_ECONOMICS = {
  ar: { pension: 0.11, health: 0.03, tax: 0.09, label: "Aportes jubilatorios + obra social" },
  us: { pension: 0.062, health: 0.0145, tax: 0.15, label: "Social Security + Medicare + impuesto federal" },
  jp: { pension: 0.0915, health: 0.05, tax: 0.05, label: "Shakai hoken (seguro social) + impuesto" },
  es: { pension: 0.047, health: 0.0, tax: 0.19, label: "Seguridad Social + IRPF" },
  mx: { pension: 0.01125, health: 0.025, tax: 0.10, label: "IMSS + ISR" },
  fr: { pension: 0.11, health: 0.0, tax: 0.09, label: "Cotisations sociales + impôt sur le revenu" },
};
function netPay(gross, countryId) {
  const r = LABOR_ECONOMICS[countryId] || LABOR_ECONOMICS.ar;
  const rate = r.pension + r.health + r.tax;
  return { net: Math.round(gross * (1 - rate)), rate, label: r.label };
}
