function subjectsForUniversityYear(degree, completedYears=0){
  const list=degree?.subjects||[];
  const perYear=Math.min(4,list.length);
  if(!perYear)return [];
  const start=(completedYears*perYear)%list.length;
  return Array.from({length:perYear},(_,i)=>list[(start+i)%list.length]);
}
function makeYearSubjects(degree, completedYears=0){
  return subjectsForUniversityYear(degree,completedYears).map((name,i)=>({
    id:`${degree.id}_y${completedYears+1}_sub_${i}`,name,progress:RandomSystem.int(0,8),
    grade:null,passed:false,needsRecovery:false,quizAttempts:0,lastQuizScore:null,lastQuizTotal:null
  }));
}
function trimLegacyUniversitySubjects(u){
  if(!u?.subjects||u.subjects.length<=4)return u;
  return {...u,subjects:u.subjects.slice(0,4)};
}


