function generateSchoolContacts(person, stage) {
  if (!stage || stage === "none" || stage === "graduated") return { stage, teachers: [], classmates: [] };
  const teacherCount = stage === "kinder" ? 2 : 4;
  const classmateCount = stage === "kinder" ? 5 : 8;
  const teachers = Array.from({ length: teacherCount }).map((_, i) => makeSchoolNpc({ role: stage === "kinder" ? "Docente de jardín" : `Profesor/a de ${SCHOOL_SUBJECTS[i % SCHOOL_SUBJECTS.length]}`, relation: "Profesor/a", age: RandomSystem.int(27, 61) }));
  const classmates = Array.from({ length: classmateCount }).map(() => makeSchoolNpc({ role: "Estudiante", relation: "Compañero/a", age: Math.max(3, person.age + RandomSystem.int(-1, 1)) }));
  return { stage, teachers, classmates };
}



// Familia extendida de la pareja: NPCs independientes, con vínculo propio con el jugador.
// Se conserva aunque termine la pareja si el vínculo personal fue suficientemente fuerte.
function generatePartnerFamily(partner, playerAge) {
  const surname = partner.name?.split(" ").slice(-1)[0] || RandomSystem.pick(SURNAMES);
  const mk = (relation, age, gender) => {
    return {...generatePerson(null,{gender,age,countryId:partner.location?.countryId,name:`${RandomSystem.pick(gender==="M"?MALE_NAMES:FEMALE_NAMES)} ${surname}`,relationship:RandomSystem.int(38,66)}),role:relation,relation,connectionThroughPartnerId:partner.id,connectionThroughPartnerName:partner.name,activeConnection:true};
  };
  const mother = mk("Madre de tu pareja", Math.max(playerAge + 20, RandomSystem.int(32, 56)), "F");
  const father = mk("Padre de tu pareja", Math.max(playerAge + 20, RandomSystem.int(33, 59)), "M");
  const siblingCount = RandomSystem.int(0, 2);
  const siblings = Array.from({length:siblingCount}).map(() => {
    const g = RandomSystem.bool() ? "M" : "F";
    const rel = g === "M" ? "Hermano de tu pareja" : "Hermana de tu pareja";
    return mk(rel, Math.max(3, partner.age + RandomSystem.int(-6, 7)), g);
  });
  const incomeLevel = RandomSystem.pick(INCOME_LEVELS).id;
  const partnerHousingByIncome = {
    low:["social_housing","with_family","renting","renting"],
    lower_middle:["renting","renting","with_family","mortgage"],
    middle:["renting","mortgage","mortgage","owned"],
    upper_middle:["mortgage","owned","owned","renting"],
    high:["owned","owned","mortgage","owned"],
  };
  const housingSituation = RandomSystem.pick(partnerHousingByIncome[incomeLevel] || ["renting"]);
  const religion = partner.religion || RandomSystem.pick(RELIGIONS).id;
  return { partnerId: partner.id, partnerName: partner.name, mother, father, siblings, introducedIds: [], createdAge: playerAge,
    household: { incomeLevel, housingSituation, religion, financialStability: RandomSystem.int(35,90) } };
}

function getPartnerFamilyMembers(person) {
  const pf = person.partnerFamily;
  if (!pf) return [];
  return [pf.mother, pf.father, ...(pf.siblings || [])].filter(Boolean);
}


