function ensureHealthCoverage(person){
  if(person.healthCoverage) return person.healthCoverage;
  const c=HEALTH_COVERAGE_BY_COUNTRY[person.location?.countryId]||HEALTH_COVERAGE_BY_COUNTRY.ar;
  const income=person.household?.incomeLevel||"middle";
  const employed=!!person.currentJob;
  if(employed && (person.currentJob.benefits||[]).some(b=>/salud|médic|seguro/i.test(b)))
    return {type:"employer",label:c.socialName,coverageRate:.85,monthlyCost:Math.round((person.currentJob.salary||1500)*.03)};
  if(["upper_middle","high"].includes(income))
    return {type:"private",label:c.privateName,coverageRate:.8,monthlyCost:120};
  if(["middle","lower_middle"].includes(income))
    return {type:"social",label:c.socialName,coverageRate:.65,monthlyCost:45};
  return {type:"public",label:c.publicName,coverageRate:1,monthlyCost:0,publicOnly:true};
}
function healthPrice(person, baseCost, provider){
  if(provider==="public") return 0;
  const cov=ensureHealthCoverage(person);
  if(provider==="coverage") return Math.max(0,Math.round(baseCost*(1-(cov.coverageRate||0))));
  return baseCost;
}
function normalizeHousingForIncome(incomeLevel,housingSituation){
  if(incomeLevel==="high" && housingSituation==="social_housing") return "owned";
  if(incomeLevel==="upper_middle" && housingSituation==="social_housing") return "mortgage";
  return housingSituation;
}
function incomeRank(id){ return ({low:1,lower_middle:2,middle:3,upper_middle:4,high:5})[id]||3; }
function religionLabel(id){ return RELIGIONS.find(r=>r.id===id)?.label||"Sin religión"; }

