function PhoneFrame({ children }) {
  return (<div className="lifesim min-h-screen w-full flex items-center justify-center p-3" style={{ background: "#DDE5EF" }}><GlobalStyles /><div className="w-full max-w-[410px] h-[840px] max-h-[94vh] overflow-hidden relative flex flex-col" style={{ background: "#fff", boxShadow: theme.shadow.phone }}>{children}</div></div>);
}
function AppScreen({ header, footer, children }) { return (<>{header}<main className="flex-1 overflow-y-auto" style={{ background: "#fff" }}>{children}</main>{footer}</>); }
function HeroHeader({ title, subtitle, onBack, brand }) {
  return (
    <header className="shrink-0" style={{ background: "#075B96" }}>
      {brand && <div className="px-4 pt-4 pb-2 text-white"><div className="font-black tracking-wide text-[19px]">✦ LIFEVERSE</div><div className="text-[10px] text-white/75">Tu historia, tus decisiones.</div></div>}
      <div className="relative px-4 py-4 flex items-center justify-center min-h-[64px]">
        {onBack && <button onClick={onBack} className="absolute left-4 w-10 h-10 rounded-full flex items-center justify-center border-2 border-white/90"><ChevronLeft size={23} color="white" /></button>}
        <div className="text-center"><div className="text-white font-black text-[22px] uppercase tracking-wide">{title}</div>{subtitle && <div className="text-white/80 text-[11px] mt-0.5">{subtitle}</div>}</div>
      </div>
    </header>
  );
}
function SectionHeader({ icon: Icon, children, right }) {
  return (<div className="px-4 py-2 flex items-center justify-between" style={{ background: "#7A7E83" }}><div className="flex items-center gap-2">{Icon && <Icon size={14} color="#fff" />}<span className="text-[12px] font-extrabold text-white">{children}</span></div>{right}</div>);
}
function GameCard({ children, accent, tint, style }) { return (<div className="px-4 py-3" style={{ background: tint || "#fff", borderLeft: accent ? `4px solid ${accent}` : undefined, borderBottom: "1px solid #C9D2DC", ...style }}>{children}</div>); }
function InfoRow({ label, value }) { return (<div className="flex items-center justify-between py-1.5 border-b last:border-b-0" style={{ borderColor: "#EEF1F5" }}><span className="text-[12px]" style={{ color: theme.color.textSecondary }}>{label}</span><span className="text-[12px] font-bold" style={{ color: theme.color.text }}>{value}</span></div>); }
function PrimaryButton({ children, onClick, loading = false, disabled = false, icon: Icon = Sparkles }) {
  return (<button onClick={onClick} disabled={disabled || loading} className="w-full py-4 text-white font-extrabold flex items-center justify-center gap-2 disabled:opacity-50" style={{ background: "#12C9C8" }}>{loading ? <Loader2 size={18} className="animate-spin" /> : <Icon size={18} />}{children}</button>);
}
function SecondaryButton({ children, onClick, icon: Icon }) { return (<button onClick={onClick} className="w-full py-3 font-bold flex items-center justify-center gap-2" style={{ color: theme.color.blue, background: "#EEF3F8" }}>{Icon && <Icon size={15} />}{children}</button>); }
function Badge({ children }) { return (<span className="px-2 py-1 rounded-full text-[10px] font-bold" style={{ background: "#E7ECF6", color: theme.color.textMuted }}>{children}</span>); }
function ErrorNotice({ message, onRetry }) { return (<div className="p-3 flex gap-2" style={{ background: "#FDEBE8" }}><AlertTriangle size={16} color={theme.color.danger} className="shrink-0 mt-0.5" /><div><div className="text-[12px] font-semibold" style={{ color: theme.color.danger }}>{message}</div>{onRetry && <button onClick={onRetry} className="mt-1 flex items-center gap-1 text-[11px] font-bold" style={{ color: theme.color.danger }}><RotateCcw size={12} />Reintentar</button>}</div></div>); }
function Chip({ children, active, onClick }) { return (<button onClick={onClick} className="px-3 py-2 rounded-full text-[11px] font-semibold border" style={{ color: active ? "white" : theme.color.textSecondary, borderColor: active ? theme.color.blue : "#E1E5EC", background: active ? theme.color.blue : "#fff" }}>{children}</button>); }
function Swatch({ value, active, onClick }) { return (<button onClick={onClick} className="w-8 h-8 rounded-full" style={{ background: value, boxShadow: active ? `0 0 0 2px white,0 0 0 4px ${theme.color.blue}` : "0 0 0 1px rgba(0,0,0,.08)" }} />); }
function StatBar({ label, value, color }) {
  return (<div className="mb-2"><div className="flex justify-between text-[11px] mb-1" style={{ color: theme.color.textSecondary }}><span>{label}</span><span className="font-bold">{value}%</span></div><div className="h-3" style={{ background: "#E1E7ED" }}><div className="h-3" style={{ width: `${value}%`, background: color }} /></div></div>);
}
function LockedTile({ label, icon: Icon, onTap }) {
  return (<button onClick={onTap} className="w-full px-4 py-4 flex items-center gap-3 text-left opacity-60 border-b" style={{ background: "#fff", borderColor: "#CDD5DF" }}><Icon size={25} color={theme.color.textMuted} /><span className="flex-1 text-[14px] font-bold" style={{ color: theme.color.textMuted }}>{label}</span><ChevronRight size={22} color={theme.color.textMuted} /></button>);
}

const CATEGORY_META = {
  familia: { icon: Users, color: "#D49C37" }, salud: { icon: Heart, color: "#E25948" }, escuela: { icon: GraduationCap, color: "#31BB8C" },
  amistades: { icon: Users, color: "#8B6CF5" }, hobbies: { icon: Sparkles, color: "#3276EC" }, economia: { icon: Wallet, color: "#1ED4C2" },
  mudanza: { icon: MapPin, color: "#596A8D" }, religion: { icon: Landmark, color: "#8B6CF5" }, conflicto: { icon: AlertTriangle, color: "#E25948" },
  oportunidad: { icon: Sparkles, color: "#31BB8C" }, adolescencia: { icon: Zap, color: "#3276EC" }, hito: { icon: Sparkles, color: "#1ED4C2" }, desarrollo: { icon: Baby, color: "#D49C37" },
};
function AgeEventGroup({ age, events, blur }) {
  return <section className={`${blur ? "vision-blur" : ""} py-2`}><div className="font-extrabold text-[14px] mb-1" style={{ color: "#075B96" }}>Edad {age} {age === 1 ? "año" : "años"}</div><div className="space-y-1.5">{events.map((ev) => <div key={ev.id} className="flex gap-2 text-[13px] leading-relaxed" style={{ color: "#666" }}>{(ev.ageMonths||0)>0&&<span className="shrink-0 text-[9px] font-black px-1.5 py-0.5 rounded-full h-fit" style={{background:"#EAF1FE",color:"#075B96"}}>{ev.ageMonths}m</span>}<span>{ev.text}</span></div>)}</div></section>;
}
function groupEventsByAge(events) {
  const ordered = [...events].sort((a,b) => (a.age-b.age) || ((a.date?.month||0)-(b.date?.month||0)) || ((a.date?.day||0)-(b.date?.day||0)));
  const groups = [];
  ordered.forEach((ev) => { const last = groups[groups.length-1]; if (last && last.age === ev.age) last.events.push(ev); else groups.push({ age: ev.age, events: [ev] }); });
  return groups;
}

function PlayerStrip({ person, onOpenProfile }) {
  const stage = LifeStageSystem.getState(person.age).stage;
  const occupation = person.schoolStage === "none" ? (stage === "baby" ? "Bebé" : "Sin escolarizar") : person.schoolStage === "graduated" ? "Graduado/a" : ({ kinder: "Jardín", primary: "Primaria", secondary: "Secundaria" }[person.schoolStage]);
  return <button onClick={onOpenProfile} className="w-full px-3 py-2 flex items-center gap-2 text-left border-b" style={{ background: "#E8EDF2", borderColor: "#AEBBC9" }}>
    <div className="w-[68px] h-[68px] flex items-center justify-center shrink-0"><CharacterAvatar appearance={person.appearance} person={person} size={64} stage={stage} age={person.age} /></div>
    <div className="flex-1 min-w-0"><div className="font-extrabold text-[15px] truncate" style={{ color: "#075B96" }}>{person.location.flag} {person.name}</div><div className="text-[11px]" style={{ color: "#075B96" }}>{occupation}</div></div>
    <div className="text-right"><div className="text-[16px] font-black" style={{ color: "#16A13A" }}>${person.economyRecord?.money ?? 0}</div><div className="text-[10px]" style={{ color: "#075B96" }}>Saldo</div></div>
  </button>;
}

/* navegación principal con botón de edad central, estilo simulador de vida */
