  function doHireResult(listing, salary, mode) {
    const company = COMPANIES.find((c) => c.id === listing.companyId);
    const ladder = jobLadder(listing.companyId);
    let person = activeCharacter.person;
    if(listing.requiredDegree && person.university?.status==="graduated"){
      const prestige=person.university.universityPrestige||65;
      const prestigeMultiplier=prestige>=80?1.08:prestige>=70?1.04:prestige<65?0.97:1;
      salary=Math.round(salary*prestigeMultiplier);
    }
    const newJob = { type: "full_time_monthly", listingId: listing.id, companyId: listing.companyId, companyName: company.name, title: listing.title, level: listing.level, salary, hoursPerWeek: listing.hoursPerWeek, schedule: listing.schedule, benefits: listing.benefits, vacationDays: listing.vacationDays, bonus: listing.bonus, performance: 60, startedAge: person.age, coworkers: [makeWorkNpc("Compañero/a"), makeWorkNpc("Compañero/a")], supervisor: makeWorkNpc(ladder[Math.min(listing.level + 1, ladder.length - 1)] || "Supervisor/a") };
    if (mode === "secondary" && person.currentJob) {
      person = { ...person, secondaryJob: newJob };
      const event = mkEvent(person, "economia", `Aceptaste un segundo trabajo como ${listing.title} en ${company.name}.`, "milestone");
      const next = { person, events: [event, ...activeCharacter.events] };
      setActiveCharacter(next); persist(next);
      return;
    }
    let workHistory = person.workHistory || [];
    const events = [];
    if (mode === "swap" && person.currentJob) {
      workHistory = [...workHistory, { ...person.currentJob, endedAge: person.age, reason: "cambio de trabajo" }];
      events.push(mkEvent(person, "economia", `Renunciaste a tu puesto anterior para aceptar ${listing.title} en ${company.name}.`, "milestone"));
    }
    person = { ...person, workHistory, currentJob: newJob };
    events.push(mkEvent(person, "economia", `Empezaste a trabajar como ${listing.title} en ${company.name}.`, "milestone"));
    const next = { person, events: [...events, ...activeCharacter.events] };
    setActiveCharacter(next); persist(next);
  }
  function doWorkAction(actionId) {
    let person = activeCharacter.person;
    if (!person.currentJob) return null;
    let text = null;
    if (actionId === "improve") {
      const key = yearKey("self", "job_performance", "improve");
      const mult = diminishMultiplier(getYearCount(person, key));
      person = bumpYearCount(person, key);
      person = { ...person, currentJob: { ...person.currentJob, performance: clampStat(person.currentJob.performance + Math.round(6 * mult)) }, stats: { ...person.stats, energy: clampStat(person.stats.energy - 4) } };
      text = mult > 0 ? "Te esforzaste y tu rendimiento mejoró." : "Ya diste lo mejor de vos este año en el trabajo, seguir insistiendo no suma mucho más.";
    } else if (actionId === "raise") {
      const chance = Math.max(0.1, Math.min(0.85, 0.25 + (person.currentJob.performance - 50) / 150 + ((person.currentJob.supervisor?.relationship || 50) - 50) / 200));
      if (RandomSystem.float() < chance) { const newSalary = Math.round(person.currentJob.salary * 1.1); person = { ...person, currentJob: { ...person.currentJob, salary: newSalary } }; text = `Te aumentaron el sueldo a $${newSalary}/mes.`; }
      else text = "Tu supervisor te dijo que todavía no es el momento.";
    } else if (actionId === "promotion") {
      const ladder = jobLadder(person.currentJob.companyId);
      const canPromote = person.currentJob.performance >= 75 && (person.age - person.currentJob.startedAge) >= 1 && person.currentJob.level + 1 < ladder.length;
      if (canPromote && RandomSystem.float() < 0.6) {
        const newLevel = person.currentJob.level + 1;
        person = { ...person, currentJob: { ...person.currentJob, level: newLevel, title: ladder[newLevel], salary: Math.round(person.currentJob.salary * 1.2), startedAge: person.age } };
        text = `¡Te ascendieron a ${ladder[newLevel]}!`;
      } else text = "Todavía no reunís las condiciones para ascender.";
    } else if (actionId === "vacation") {
      person = applyEffects(person, { happiness: 6, stress: -8 });
      text = "Tomaste unos días de vacaciones.";
    } else if (actionId === "quit") {
      const quitTitle = person.currentJob.title;
      const workHistory = [...(person.workHistory || []), { ...person.currentJob, endedAge: person.age, reason: "renuncia" }];
      person = { ...person, currentJob: null, workHistory };
      text = `Renunciaste a tu puesto de ${quitTitle}.`;
    }
    const event = text ? mkEvent(person, "economia", text, "minor") : null;
    const next = { person, events: event ? [event, ...activeCharacter.events] : activeCharacter.events };
    setActiveCharacter(next); persist(next);
    return text;
  }
  function doOrganizeHangout(friendIds, plan) {
    const { person, event, followUp, summary } = resolveHangout(activeCharacter.person, friendIds, plan);
    const next = { person, events: event ? [event, ...activeCharacter.events] : activeCharacter.events };
    setActiveCharacter(next);
    if (followUp) setDecisionQueue((q) => [followUp, ...q]); else persist(next);
    return summary;
  }

  function doChatMessage(npcId, npcType, message) {
    let p = structuredClone(activeCharacter.person);
    const npc = getNpcById(p, npcId);
    if (!npc) return { history: [] };
    const {reply,delta,npcPatch}=localNpcReply(npc,p,message);
    p=updateNpcById(p,npcId,n=>({
      ...(npcPatch||{}),
      relationship:clampStat((n.relationship||50)+(delta.relationship||0)),
      trust:clampStat((n.trust||50)+(delta.trust||0)),
      closeness:clampStat((n.closeness||50)+(delta.closeness||0)),
      resentment:clampStat((n.resentment||0)+(delta.resentment||0)),
      chatHistory:[...(n.chatHistory||[]),{role:"player",text:message,age:p.age},{role:"npc",text:reply,age:p.age}].slice(-40),
      memories:(delta.relationship||0)<=-4||npcPatch?[...(n.memories||[]),{id:RandomSystem.id(),type:npcPatch?"relationship_start":"conversation_conflict",text:npcPatch?`Empezaron a salir a los ${p.age} años.`:"Tuvieron una conversación que terminó mal.",age:p.age}].slice(-12):(n.memories||[])
    }));
    const updated=getNpcById(p,npcId);
    const next={...activeCharacter,person:p}; setActiveCharacter(next); persist(next);
    return {history:updated?.chatHistory||[]};
  }

  function doConfirmRelationship(npcId, npcType) {
    let p = structuredClone(activeCharacter.person);
    const npc = getNpcById(p, npcId);
    if (!npc || !npc.pendingRelationshipOffer) return null;
    p = updateNpcById(p, npcId, (n) => ({
      pendingRelationshipOffer: false,
      romanticStatus: `en pareja con ${p.name}`,
      relationship: clampStat((n.relationship || 50) + 6),
      trust: clampStat((n.trust || 50) + 4),
      closeness: clampStat((n.closeness || 50) + 6),
      memories: [...(n.memories || []), { id: RandomSystem.id(), type: "relationship_start", text: `Empezaron una relación a los ${p.age} años.`, age: p.age }].slice(-12),
    }));
    const compatibility = Math.round(pairAffinity(p.id, npcId) * 100);
    p = { ...p,
      romanticPartnerId: npcId,
      romanticPartnerSnapshot: { ...npc, pendingRelationshipOffer:false, romanticStatus:`en pareja con ${p.name}` },
      romanticRelationship: {
        id: RandomSystem.id(), partnerId: npcId, label: p.age < 18 ? "Novio/a" : "Pareja",
        startedAge: p.age, partnerStartedAge: npc.age, status: "active", affection: clampStat((npc.relationship||50)+8),
        trust: npc.trust||50, attraction: RandomSystem.int(60,92), compatibility,
        communication: npc.closeness||50, resentment: npc.resentment||0, milestones: [], childrenDiscussed:false, childrenPreference:null, protectionDiscussed:false, protectionPlan:null, livingTogether:false, engaged:false, married:false, childcarePlayerShare:null, childResidence:null, prenup:false, weddingPlan:null
      },
      partnerFamily: p.partnerFamily?.partnerId === npcId ? p.partnerFamily : generatePartnerFamily(npc, p.age),
      romanticHistory: [...(p.romanticHistory||[])]
    };
    const event = mkEvent(p, "amistades", `${npc.name} y vos empezaron a ser pareja.`, "milestone");
    const next = { person: p, events: [event, ...activeCharacter.events] };
    setActiveCharacter(next);

    if (p.age < 18) {
      const mom = p.family.mother, dad = p.family.father;
      const householdReligion = p.religion || "ninguna";
      const partnerHouse = p.partnerFamily?.household;
      const playerIncome = incomeRank(p.household?.incomeLevel);
      const partnerIncome = incomeRank(partnerHouse?.incomeLevel);
      const upbringingConservatism = p.upbringing === "estricta" ? 22 : p.upbringing === "liberal" ? -10 : 5;
      const religionConservatism = householdReligion !== "ninguna" ? 12 : 0;
      const religionMismatch = partnerHouse && householdReligion !== "ninguna" && partnerHouse.religion !== householdReligion ? 13 : 0;
      const classGap = Math.abs(playerIncome-partnerIncome)>=2 ? 9 : 0;
      const relationshipBase = ((mom.relationship||50)+(dad.relationship||50)+(mom.trust||50)+(dad.trust||50))/4;
      const acceptanceScore = relationshipBase - upbringingConservatism - religionConservatism - religionMismatch - classGap + RandomSystem.int(-12,12);
      const approve = acceptanceScore >= 45;
      const reasons=[];
      if(upbringingConservatism>=20) reasons.push("son muy estrictos con las relaciones");
      if(religionMismatch) reasons.push("les preocupa la diferencia religiosa entre las familias");
      if(classGap) reasons.push("también juzgan la diferencia económica entre ambas familias");
      if(!reasons.length) reasons.push("principalmente les importa tu edad y cuánto conocen a tu pareja");
      const parentText = approve
        ? `Tus padres se enteraron de que empezaste a salir con ${npc.name}. En general lo aceptan. ${reasons.join(" y ")}. Quieren conocer mejor a tu pareja antes de confiar del todo.`
        : `Tus padres se enteraron de que empezaste a salir con ${npc.name} y no están de acuerdo por ahora: ${reasons.join(" y ")}. Su postura puede cambiar según cómo avance la relación.`;
      const parentDecision = {
        id:"parents_react_relationship", cat:"familia", text: parentText,
        options: approve ? [
          { label:"Proponer que conozcan a tu pareja", effects:{ familyRelationship:2 }, result:`Les propusiste conocer a ${npc.name} y a su familia.` },
          { label:"Contarles más sobre su familia", effects:{ familyRelationship:1 }, result:"Les hablaste de la familia y situación de tu pareja." }
        ] : [
          { label:"Escuchar sus motivos", effects:{ familyRelationship:1, stress:1 }, result:"Escuchaste por qué desaprueban la relación." },
          { label:"Defender la relación", effects:{ familyRelationship:-2, stress:2 }, result:`Les dijiste que querés seguir saliendo con ${npc.name}.` },
          { label:"Pedirles que conozcan a su familia antes de juzgar", effects:{ familyRelationship:1 }, result:"Les pediste que conozcan a la otra familia antes de decidir." }
        ]
      };
      setDecisionQueue((q)=>[parentDecision,...q]);
    } else persist(next);
    return `Ahora vos y ${npc.name} son pareja.`;
  }


