          p.romanticRelationship={id:RandomSystem.id(),partnerId:ex.id,label:"Pareja",startedAge:p.age,status:"active",affection:ex.relationship||55,trust:ex.trust||45,attraction:ex.attraction||60,compatibility:Math.round(pairAffinity(p.id,ex.id)*100),communication:ex.closeness||50,resentment:ex.resentment||0,milestones:[],childrenDiscussed:false,childrenPreference:null,protectionDiscussed:false,protectionPlan:null,livingTogether:false,engaged:false,married:false,prenup:false,weddingPlan:null};
